ALTER TABLE SRM_SUPPLIER_CONTACT ADD ROW_VERSION bigint NOT NULL DEFAULT 0;
ALTER TABLE SRM_SUPPLIER_CERT ADD SERIES_ID varchar(20) NULL;
UPDATE SRM_SUPPLIER_CERT SET SERIES_ID=ID;
ALTER TABLE SRM_SUPPLIER_CERT MODIFY SERIES_ID varchar(20) NOT NULL, ADD CONSTRAINT uq_cert_series UNIQUE(SUPPLIER_ID,SERIES_ID,VERSION);
ALTER TABLE SRM_BUSINESS_EVENT ADD EVENT_DOCUMENT text NULL, ADD SIGNATURE varchar(256) NULL;
CREATE TABLE SRM_CATEGORY(CODE varchar(32) PRIMARY KEY,NAME varchar(64) NOT NULL,REQUIRED_CERTS json NOT NULL,ENABLED boolean NOT NULL DEFAULT true,ROW_VERSION bigint NOT NULL DEFAULT 0);
INSERT INTO SRM_CATEGORY(CODE,NAME,REQUIRED_CERTS) VALUES
 ('MACHINING','精密加工','["BUSINESS_LICENSE","ISO9001"]'),('METAL','金属材料','["BUSINESS_LICENSE","ISO9001"]'),
 ('EQUIPMENT','设备与服务','["BUSINESS_LICENSE"]'),('ELECTRONICS','电子元器件','["BUSINESS_LICENSE","ISO9001"]'),('PACKAGING','包装辅料','["BUSINESS_LICENSE"]');
CREATE TABLE SRM_PORTAL_ACCOUNT_RESERVATION(CONTACT_ID varchar(20) PRIMARY KEY,ACCOUNT varchar(64) NOT NULL UNIQUE);
CREATE TABLE SRM_CERT_ALERT(ID varchar(20) PRIMARY KEY,ORG_ID varchar(20) NOT NULL,SUPPLIER_ID varchar(20) NOT NULL,CERT_ID varchar(20) NOT NULL,VALID_TO date NOT NULL,KIND varchar(16) NOT NULL,STATUS varchar(16) NOT NULL DEFAULT 'PENDING',CREATED_AT datetime(3) NOT NULL, UNIQUE(CERT_ID,VALID_TO,KIND), INDEX idx_alert_scope(ORG_ID,SUPPLIER_ID));
-- Enforce native account uniqueness when the Snowy account table exists. Fail on duplicate historical accounts rather than choose one.
SET @srm_client_sql=IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='CLIENT_USER')>0,'CREATE UNIQUE INDEX uq_srm_client_account ON CLIENT_USER(ACCOUNT)','SELECT 1');
PREPARE srm_stmt FROM @srm_client_sql; EXECUTE srm_stmt; DEALLOCATE PREPARE srm_stmt;
